input.command:
mkdir -p /tmp/fpp && cat > /tmp/fpp/scan.py <<'EOF'
import json, glob, os, re, shlex, collections
files = sorted(glob.glob(os.path.expanduser('~/.claude/projects/*/*.jsonl')) + glob.glob(os.path.expanduser('~/.claude/projects/*/*/subagents/*.jsonl')), key=os.path.getmtime, reverse=True)[:50]
c = collections.Counter(); mcp = collections.Counter(); ex = {}
for f in files:
    for line in open(f, errors='ignore'):
        try: o = json.loads(line)
        except: continue
        if o.get('type') != 'assistant': continue
        for b in (o.get('message', {}).get('content') or []):
            if not isinstance(b, dict) or b.get('type') != 'tool_use': continue
            n = b.get('name', '')
            if n.startswith('mcp__'): mcp[n] += 1; continue
            if n != 'Bash': continue
            cmd = b.get('input', {}).get('command', '')
            for seg in re.split(r'\|\||&&|;|\||\n', cmd):
                seg = seg.strip()
                if not seg: continue
                try: t = shlex.split(seg)
                except: t = seg.split()
                while t and (re.match(r'^\w+=', t[0]) or t[0] in ('sudo', 'timeout', 'time', 'env')):
                    t = t[1:]
                    if t and re.match(r'^\d+[smh]?$', t[0]): t = t[1:]
                if not t: continue
                k = t[0] if len(t) < 2 or t[1].startswith('-') else t[0] + ' ' + t[1]
                if t[0] in ('npm', 'git', 'gh', 'docker', 'vercel', 'npx', 'pnpm', 'yarn'):
                    k = ' '.join(t[:3]) if t[0] == 'npm' and len(t) > 2 and t[1] == 'run' else k
                c[k] += 1; ex.setdefault(k, seg[:100])
print(len(files), 'files')
for k, v in c.most_common(70): print(v, '|', k, '|', ex[k])
print('MCP'); [print(v, k) for k, v in mcp.most_common(20)]
EOF
python3 -I /tmp/fpp/scan.py; cat /Users/dinakar/Documents/coding/anthropic_take_home/.claude/settings.json 2>&1

