}

export type GateDecision =
  | { action: "show" }
  | { action: "defer"; reason: string }
  | { action: "skip"; reason: "one_at_a_time" | "low_value" | "mastered" | "off_band" | "cap" | "unverified" };

export type DifficultyKind = "first_exposure" | "practice" | "boss";

/** Engine summary rendered into the work model's dynamic context each turn. */
export interface EngineSummary {
  guardrails: { enabled: boolean; mode: GuardrailMode };
  valueThreshold: number;
  targetDifficulty: { firstExposure: number; practice: number }; // for a typical unseen/seen concept
  masteredConcepts: string[];
  conceptsSinceBoss: string[];
  rollingAccuracy: number | null; // over last 5 graded outcomes
  recentOutcomes: { concept: string; type: string; score: number }[]; // last 3
}

export type XpEvent =
  | { kind: "answer"; verdict: Verdict; afterMC: boolean }
  | { kind: "prediction"; verdict: Verdict }
  | { kind: "boss_hit"; partial: boolean }
  | { kind: "boss_outcome"; outcome: BossOutcome }
  | { kind: "session_complete" };

export interface LevelInfo {
  level: number;
  xp: number;
  levelStartXp: number;
  nextLevelXp: number;
}

export interface LevelReward {
  level: number;
  kind: "theme" | "sound_pack";
  id: string;
  label: string;
}

/** Signatures Track B must export from lib/engine/index.ts. */
export interface EngineApi {
  gate(candidate: LearningMomentInput, ctx: GateContext): GateDecision;
  updateMastery(prev: ConceptMastery | undefined, score: number, difficulty: number, familiarity: Familiarity, now: number): ConceptMastery;
  targetDifficulty(m: ConceptMastery | undefined, kind: DifficultyKind, familiarity: Familiarity, recent: Outcome[]): number;
  isMastered(m: ConceptMastery | undefined): boolean;
  reviewDue(m: ConceptMastery | undefined, now: number): boolean;
  bossDue(state: EngineState, now: number, sessionEndsAt: number): boolean;
  bossOutcome(hits: number, maxHits: number): BossOutcome;
  summarize(ctx: GateContext): EngineSummary;
  recordShown(state: EngineState, momentId: string, now: number): EngineState;
  recordOutcome(state: EngineState, outcome: Outcome): EngineState;
  recordWorkTurn(state: EngineState): EngineState;
  xpFor(event: XpEvent): number;
  levelFor(totalXp: number): LevelInfo;
  rewardsBetween(fromLevel: number, toLevel: number): LevelReward[];
}
/**
 * Browser helper for POST /api/chat: posts a ChatRequest and delivers each NDJSON ChatStreamEvent.
 * Every stream ends with a `turn_end` event; if the connection drops first, a synthetic error + turn_end is delivered.
 */
import type { ChatRequest } from "@/lib/contracts/api";
import type { ChatStreamEvent } from "@/lib/contracts/stream";

export interface NdjsonParse {
  events: ChatStreamEvent[];
  /** Incomplete trailing line, to prepend to the next chunk. */
  rest: string;
}

/** Splits buffered text into complete NDJSON lines. Blank and malformed lines are skipped. */
export function parseNdjsonChunks(buffer: string, chunk: string): NdjsonParse {
  const lines = (buffer + chunk).split("\n");
  const rest = lines.pop() ?? "";
  const events: ChatStreamEvent[] = [];
  for (const line of lines) {
    const event = parseLine(line);
    if (event) events.push(event);
  }
  return { events, rest };
}

function parseLine(line: string): ChatStreamEvent | null {
  const trimmed = line.trim();
  if (!trimmed) return null;
  try {
    const value: unknown = JSON.parse(trimmed);
    return value && typeof value === "object" && typeof (value as { type?: unknown }).type === "string" ? (value as ChatStreamEvent) : null;
  } catch {
    return null;
  }
}

const lostConnection: Extract<ChatStreamEvent, { type: "error" }> = { type: "error", message: "The connection dropped before Claude finished. Try again.", retryable: true, code: "upstream" };

export async function streamChat(req: ChatRequest, onEvent: (event: ChatStreamEvent) => void, signal?: AbortSignal): Promise<void> {
  let ended = false;
  const deliver = (event: ChatStreamEvent) => {
    if (event.type === "turn_end") ended = true;
    onEvent(event);
  };
  const fail = (event: ChatStreamEvent) => {
    deliver(event);
    deliver({ type: "turn_end", reason: "error" });
  };

  let res: Response;
  try {
    res = await fetch("/api/chat", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(req),
      signal,
    });
  } catch {
    if (signal?.aborted) return;
    return fail({ ...lostConnection, message: "Couldn't reach the server. Check your connection and try again." });
  }

  if (!res.ok || !res.body) {
    const body = (await res.json().catch(() => null)) as { error?: string } | null;
    return fail({
      type: "error",
      message: body?.error ?? "Something went wrong. Try again.",
      retryable: res.status >= 500 || res.status === 429,
      code: res.status === 429 ? "rate_limited" : res.status >= 500 ? "upstream" : "bad_request",
    });
  }

  const reader = res.body.pipeThrough(new TextDecoderStream()).getReader();
  let buffer = "";
  try {
    for (;;) {
      const { value, done } = await reader.read();
      if (done) break;
      const parsed = parseNdjsonChunks(buffer, value);
      buffer = parsed.rest;
      parsed.events.forEach(deliver);
    }
    parseNdjsonChunks(buffer, "\n").events.forEach(deliver);
  } catch {
    if (signal?.aborted) return;
  } finally {
    reader.releaseLock();
  }
  if (!ended && !signal?.aborted) fail(lostConnection);
}

export { applyEvent } from "./transcript";
/**
 * Pure reducer that builds transcript state from chat stream events. Item ids match the server's persisted
 * transcript, so a reloaded session (GET /api/session/[id]) renders the same items.
 */
import type { TranscriptItem } from "@/lib/contracts/session";
import type { ChatStreamEvent } from "@/lib/contracts/stream";

type CodeRun = Extract<TranscriptItem, { kind: "code_run" }>;

function upsert(items: TranscriptItem[], id: string, make: () => TranscriptItem, update: (item: TranscriptItem) => TranscriptItem): TranscriptItem[] {
  const at = items.findIndex((i) => i.id === id);
  if (at === -1) return [...items, make()];
  const next = items.slice();
  next[at] = update(items[at]);
  return next;
}

const addOnce = (items: TranscriptItem[], item: TranscriptItem) => (items.some((i) => i.id === item.id) ? items : [...items, item]);

/** Returns the next transcript (a new array when something changed; the same array otherwise). */
export function applyEvent(items: TranscriptItem[], event: ChatStreamEvent): TranscriptItem[] {
  switch (event.type) {
    case "text_delta":
      return upsert(
        items,
        event.itemId,
        () => ({ kind: "assistant_text", id: event.itemId, text: event.text }),
        (item) => (item.kind === "assistant_text" ? { ...item, text: item.text + event.text } : item),
      );
    case "code_start":
      return upsert(
        items,
        event.itemId,
        () => ({ kind: "code_run", id: event.itemId, language: event.language, code: event.code, fileIds: [] }),
        (item) => (item.kind === "code_run" ? { ...item, language: event.language, code: event.code } : item),
      );
    case "code_result": {
      const result = { stdout: event.stdout, stderr: event.stderr, returnCode: event.returnCode, fileIds: event.fileIds };
      return upsert(
        items,
        event.itemId,
        (): CodeRun => ({ kind: "code_run", id: event.itemId, language: "bash", code: "", ...result }),
        (item) => (item.kind === "code_run" ? { ...item, ...result } : item),
      );
    }
    case "moment":
      return addOnce(items, { kind: "moment", id: event.itemId, momentId: event.moment.id });
    case "prediction_reveal":
      return addOnce(items, {
        kind: "prediction_reveal",
        id: event.itemId,
        momentId: event.momentId,
        actualResult: event.actualResult,
        verdict: event.verdict,
        why: event.why,
        xp: event.xp.amount,
      });
    case "milestone":
      return addOnce(items, { kind: "milestone", id: event.itemId, label: event.label });
    case "notice":
      return addOnce(items, { kind: "notice", id: event.itemId, text: event.text });
    case "status":
    case "turn_end":
    case "error":
      return items;
  }
}
/** Server → client view mappers (shared). Never leak answer keys to the browser. */
import type { MomentView } from "@/lib/contracts/moment";
import type { BossState, MomentRecord, Session, TranscriptItem, User } from "@/lib/contracts/session";
import type { BossView, SessionView, UserView } from "@/lib/contracts/api";
import { engine } from "@/lib/engine";

export function toMomentView(m: MomentRecord): MomentView {
  const revealMC = m.mcOffered;
  return {
    id: m.id,
    sessionId: m.sessionId,
    type: m.type,
    concept: m.candidate.concept,
    conceptCard: m.candidate.concept_card,
    question: m.candidate.question,
    mcOptions: revealMC ? m.candidate.mc_fallback.options : undefined,
    status: m.status,
    bossId: m.bossId,
    answer: m.answer,
    mcChoice: m.mcChoice,
    verdict: m.verdict,
    why: m.why,
    correctIndex: m.mcChoice !== undefined ? m.candidate.mc_fallback.correct_index : undefined,
    xp: m.xp,
  };
}

export function toBossView(b: BossState, moments: MomentRecord[]): BossView {
  const current = b.momentIds.find((id) => {
    const m = moments.find((x) => x.id === id);
    return m && m.status === "awaiting_answer";
  });
  return { id: b.id, name: b.name, ascii: b.ascii, intro: b.intro, hp: b.hp, maxHp: b.maxHp, momentIds: b.momentIds, currentMomentId: current, outcome: b.outcome };
}

export function toUserView(u: User): UserView {
  return { xp: u.xp, level: engine.levelFor(u.xp), unlocks: u.unlocks, settings: u.settings };
}

export function toSessionView(s: Session, transcript: TranscriptItem[], moments: MomentRecord[], bosses: BossState[]): SessionView {
  return {
    id: s.id,
    title: s.title,
    intent: s.intent,
    sketch: s.sketch,
    status: s.status,
    createdAt: s.createdAt,
    endsAt: s.createdAt + s.intent.minutes * 60_000,
    transcript,
    moments: Object.fromEntries(moments.map((m) => [m.id, toMomentView(m)])),
    bosses: Object.fromEntries(bosses.map((b) => [b.id, toBossView(b, moments)])),
    chapters: Object.fromEntries(s.story.chapters.map((c) => [c.id, c])),
  };
}

