"use client";

import type { ReactNode } from "react";
import { LazyMotion, MotionConfig, domAnimation } from "motion/react";
import { SoundProvider } from "./SoundProvider";
import { useApplyTheme } from "@/lib/ui/useApplyTheme";

export interface UiProvidersProps {
  sound?: { enabled: boolean; volume: number; pack: string };
  /** Theme id to apply to <html data-theme>. */
  theme?: string;
  children: ReactNode;
}

/**
 * Wrap the app (or the workspace) once: Motion with reduced-motion support, sounds, and the active theme.
 * Components use `m.*` from motion/react, so animations need this LazyMotion parent.
 */
export function UiProviders({ sound, theme, children }: UiProvidersProps) {
  useApplyTheme(theme);
  return (
    <LazyMotion features={domAnimation} strict>
      <MotionConfig reducedMotion="user">
        <SoundProvider enabled={sound?.enabled} volume={sound?.volume} pack={sound?.pack}>
          {children}
        </SoundProvider>
      </MotionConfig>
    </LazyMotion>
  );
}
"use client";

import { createContext, useContext, useEffect, useMemo, useState, type ReactNode } from "react";
import type { Verdict } from "@/lib/contracts/moment";
import {
  DEFAULT_SOUND_PACK,
  DEFAULT_VOLUME,
  SoundManager,
  type PlayOptions,
  type SoundEvent,
  type SoundPackId,
} from "@/lib/sound";

export interface SoundApi {
  play(event: SoundEvent, opts?: PlayOptions): void;
  /** correct → chime (rising with the streak), partial → softer chime, incorrect → gentle low note. */
  playVerdict(verdict: Verdict): void;
  /** Plays a sample of a pack (settings picker), ignoring the current pack. */
  preview(pack: SoundPackId, event?: SoundEvent): void;
}

const NOOP: SoundApi = { play() {}, playVerdict() {}, preview() {} };
const SoundContext = createContext<SoundApi>(NOOP);

export interface SoundProviderProps {
  enabled?: boolean;
  volume?: number;
  pack?: string;
  /** For tests: inject a manager with a fake AudioContext. */
  manager?: SoundManager;
  children: ReactNode;
}

/** Owns the single SoundManager; unlocks audio on the first pointer/key gesture. */
export function SoundProvider({ enabled = true, volume = DEFAULT_VOLUME, pack = DEFAULT_SOUND_PACK, manager: injected, children }: SoundProviderProps) {
  const [manager] = useState(() => injected ?? new SoundManager());

  useEffect(() => {
    manager.configure({ enabled, volume, pack });
  }, [manager, enabled, volume, pack]);

  useEffect(() => {
    if (manager.isUnlocked) return;
    const opts = { capture: true } as const;
    const onGesture = () => {
      manager.unlock();
      if (manager.isUnlocked) remove();
    };
    const remove = () => {
      window.removeEventListener("pointerdown", onGesture, opts);
      window.removeEventListener("keydown", onGesture, opts);
    };
    window.addEventListener("pointerdown", onGesture, opts);
    window.addEventListener("keydown", onGesture, opts);
    return remove;
  }, [manager]);

  const api = useMemo<SoundApi>(
    () => ({
      play: (event, opts) => void manager.play(event, opts),
      playVerdict: (verdict) => void manager.playVerdict(verdict),
      preview: (p, event = "correct") => void manager.play(event, { pack: p }),
    }),
    [manager],
  );

  return <SoundContext.Provider value={api}>{children}</SoundContext.Provider>;
}

/** Sound API; a silent no-op outside a SoundProvider. */
export function useSounds(): SoundApi {
  return useContext(SoundContext);
}
"use client";

import { useEffect } from "react";
import { applyTheme } from "@/lib/themes";

/** Keeps <html data-theme> in sync with the user's chosen theme. */
export function useApplyTheme(themeId: string | undefined) {
  useEffect(() => {
    if (themeId) applyTheme(themeId);
  }, [themeId]);
}
/**
 * Confetti for the two biggest moments only (level-up, boss victory). P2: one celebration per milestone,
 * so each key fires once and a cooldown stops back-to-back bursts (e.g. a boss win that also levels you up).
 * canvas-confetti skips itself when the user prefers reduced motion.
 */
export type CelebrationKind = "levelUp" | "bossVictory";

const COOLDOWN_MS = 4000;
const fired = new Set<string>();
let lastAt = -Infinity;

function themeColors(): string[] {
  const s = getComputedStyle(document.documentElement);
  const colors = ["--primary", "--accent", "--success"].map((v) => s.getPropertyValue(v).trim()).filter(Boolean);
  return colors.length ? colors : ["#2f6faf", "#7fb3e0", "#2e7d5b"];
}

/** Returns true if confetti fired. `key` identifies the milestone (e.g. "levelup:3", "boss:<id>"). */
export async function celebrate(key: string, kind: CelebrationKind = "levelUp"): Promise<boolean> {
  if (typeof window === "undefined" || fired.has(key)) return false;
  const now = Date.now();
  if (now - lastAt < COOLDOWN_MS) return false;
  fired.add(key);
  lastAt = now;
  const { default: confetti } = await import("canvas-confetti");
  await confetti({
    particleCount: kind === "bossVictory" ? 120 : 80,
    spread: kind === "bossVictory" ? 90 : 70,
    startVelocity: 35,
    ticks: 180,
    scalar: 0.9,
    origin: { y: 0.7 },
    colors: themeColors(),
    disableForReducedMotion: true,
  });
  return true;
}
"use client";

import { useSyncExternalStore } from "react";

/** Current time in ms, ticking every `intervalMs`. Returns null during SSR/hydration to avoid mismatches. */
export function useNow(intervalMs = 1000): number | null {
  return useSyncExternalStore(
    (notify) => {
      const id = setInterval(notify, intervalMs);
      return () => clearInterval(id);
    },
    () => Math.floor(Date.now() / intervalMs) * intervalMs,
    () => null,
  );
}
/**
 * Theme registry (Track C). Token overrides live in app/themes.css as [data-theme="<id>"] blocks.
 * Palettes and contrast notes: reference/research/04-ui-themes.md.
 */

export type ThemeId = "frost" | "sunset" | "forest" | "night" | "sakura" | "parchment" | "matcha";

export interface ThemeDef {
  id: ThemeId;
  label: string;
  unlockLevel: number;
  /** [background, primary, accent] for the picker swatch. */
  swatch: [string, string, string];
  dark?: boolean;
}

export const DEFAULT_THEME: ThemeId = "frost";

export const THEMES: readonly ThemeDef[] = [
  { id: "frost", label: "Frost", unlockLevel: 1, swatch: ["#f4f8fb", "#2f6faf", "#7fb3e0"] },
  { id: "sunset", label: "Sunset", unlockLevel: 2, swatch: ["#fff4ec", "#a8432c", "#f4a261"] },
  { id: "forest", label: "Forest", unlockLevel: 4, swatch: ["#f1f5ee", "#3f6b4a", "#a3c49a"] },
  { id: "night", label: "Night Sky", unlockLevel: 5, swatch: ["#141b2d", "#8fb8ff", "#f2d27a"], dark: true },
  { id: "sakura", label: "Sakura", unlockLevel: 7, swatch: ["#fdf3f5", "#a8445f", "#f5b8c8"] },
  { id: "parchment", label: "Parchment", unlockLevel: 8, swatch: ["#f5ecd7", "#7a4e2d", "#c9a227"] },
  { id: "matcha", label: "Matcha", unlockLevel: 10, swatch: ["#f3f5ec", "#55703b", "#c5d6a0"] },
];

export function getTheme(id: string): ThemeDef | undefined {
  return THEMES.find((t) => t.id === id);
}

/**
 * A theme is usable if it's a level-1 theme, the server lists it in the user's unlocks,
 * or (optionally) the user's level already reaches its unlock level.
 */
export function isUnlocked(themeId: string, unlockedIds: readonly string[], level?: number): boolean {
  const theme = getTheme(themeId);
  if (!theme) return false;
  if (theme.unlockLevel <= 1) return true;
  if (unlockedIds.includes(themeId)) return true;
  return level !== undefined && level >= theme.unlockLevel;
}

/** Sets <html data-theme>. Unknown ids fall back to the default theme. Returns the applied id. */
export function applyTheme(id: string): ThemeId {
  const theme = getTheme(id)?.id ?? DEFAULT_THEME;
  if (typeof document !== "undefined") {
    document.documentElement.dataset.theme = theme;
    document.documentElement.style.colorScheme = getTheme(theme)?.dark ? "dark" : "light";
  }
  return theme;
}
