"use client";

import { useId, useState } from "react";
import type { Familiarity } from "@/lib/contracts/engine";
import type { Intent } from "@/lib/contracts/session";
import { Pip } from "./Pip";
import { useSounds } from "./SoundProvider";
import { Button, Chip, focusRing } from "./ui";

export const DEMO_GOAL = "Help me train a model to predict customer churn from this CSV.";

const FAMILIARITY: { id: Familiarity; label: string }[] = [
  { id: "new", label: "New to this" },
  { id: "some", label: "Some experience" },
  { id: "comfortable", label: "Comfortable" },
];
const MINUTES = [10, 20, 30] as const;

export interface IntentFlowProps {
  onComplete: (intent: Intent) => void;
  /** Disable the final button while the session is being created. */
  busy?: boolean;
  autoFocus?: boolean;
}

/** Intent step: goal (or the demo starter), then familiarity + time chips. */
export function IntentFlow({ onComplete, busy = false, autoFocus = true }: IntentFlowProps) {
  const [step, setStep] = useState<"goal" | "details">("goal");
  const [goal, setGoal] = useState("");
  const [demo, setDemo] = useState(false);
  const [familiarity, setFamiliarity] = useState<Familiarity | null>(null);
  const [minutes, setMinutes] = useState<number>(10);
  const sounds = useSounds();
  const goalId = useId();
  const famLabel = useId();
  const timeLabel = useId();

  function next() {
    if (!goal.trim()) return;
    setStep("details");
  }

  function startDemo() {
    sounds.play("click");
    setGoal(DEMO_GOAL);
    setDemo(true);
    setStep("details");
  }

  function finish() {
    if (!familiarity || busy) return;
    onComplete({ goal: goal.trim(), familiarity, minutes, demo: demo && goal.trim() === DEMO_GOAL });
  }

  if (step === "goal") {
    return (
      <div className="mx-auto flex w-full max-w-xl flex-col items-center gap-5">
        <Pip mood="happy" />
        <label htmlFor={goalId} className="text-center text-xl font-bold">What are you working on?</label>
        <textarea
          id={goalId}
          autoFocus={autoFocus}
          rows={3}
          value={goal}
          maxLength={1000}
          placeholder="e.g. Analyze our signup funnel in SQL, or draft a project plan…"
          onChange={(e) => { setGoal(e.target.value); setDemo(e.target.value.trim() === DEMO_GOAL); }}
          onKeyDown={(e) => {
            if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) { e.preventDefault(); next(); }
          }}
          className="w-full resize-none rounded-card border border-border bg-surface p-4 leading-relaxed shadow-soft outline-none placeholder:text-muted focus:border-primary"
        />
        <div className="flex w-full flex-wrap items-center justify-center gap-3">
          <button
            type="button"
            onClick={startDemo}
            className={`rounded-full bg-primary px-5 py-2.5 font-semibold text-primary-foreground shadow-soft transition hover:brightness-110 ${focusRing}`}
          >
            <span aria-hidden="true">▶ </span>Try the demo: train a churn model
          </button>
          <Button onClick={next} disabled={!goal.trim()}>Next</Button>
        </div>
      </div>
    );
  }

  return (
    <div className="mx-auto flex w-full max-w-xl flex-col items-center gap-6">
      <Pip mood="neutral" />
      <div className="w-full rounded-card bg-surface-2 px-4 py-3 text-sm">
        <span className="font-bold text-muted">Working on: </span>
        <span>{goal.trim()}</span>{" "}
        <button type="button" onClick={() => setStep("goal")} className={`rounded font-semibold text-primary underline underline-offset-2 ${focusRing}`}>
          Change
        </button>
      </div>

      <div className="flex w-full flex-col items-center gap-3">
        <p id={famLabel} className="text-lg font-bold">How familiar are you with this?</p>
        <div role="group" aria-labelledby={famLabel} className="flex flex-wrap justify-center gap-2">
          {FAMILIARITY.map((f) => (
            <Chip key={f.id} selected={familiarity === f.id} onClick={() => { sounds.play("click"); setFamiliarity(f.id); }}>
              {f.label}
            </Chip>
          ))}
        </div>
      </div>

      <div className="flex w-full flex-col items-center gap-3">
        <p id={timeLabel} className="text-lg font-bold">How long do you have?</p>
        <div role="group" aria-labelledby={timeLabel} className="flex flex-wrap justify-center gap-2">
          {MINUTES.map((n) => (
            <Chip key={n} selected={minutes === n} onClick={() => { sounds.play("click"); setMinutes(n); }}>
              {n} min
            </Chip>
          ))}
        </div>
      </div>

      <Button variant="primary" onClick={finish} disabled={!familiarity || busy}>
        {busy ? "Starting…" : "Let's go"}
      </Button>
    </div>
  );
}
"use client";

import { useEffect, useId, useRef, useState } from "react";
import type { MomentView, Verdict } from "@/lib/contracts/moment";
import type { XpAward } from "@/lib/contracts/stream";
import { Markdown } from "./Markdown";
import { Pip } from "./Pip";
import { useSounds } from "./SoundProvider";
import { Button, Spinner, VERDICT_LABEL, VerdictChip, XpChip, focusRing } from "./ui";
import { MOMENT_TYPE_LABEL, feedbackKey, momentPhase, pipMoodFor, type MomentPhase } from "./momentPhase";

export interface MomentHandlers {
  onSubmit: (answer: string) => void;
  onShowOptions: () => void;
  onChooseOption: (index: number) => void;
  onSkip: () => void;
  onDefer: () => void;
  onReport: () => void;
}

/** Mirrors GradeRequest["action"], so P2 can route every card action through one function. */
export type MomentAction =
  | { kind: "submit"; answer: string }
  | { kind: "mc"; choice: number }
  | { kind: "show_options" }
  | { kind: "skip" }
  | { kind: "defer" }
  | { kind: "report" };

export function momentHandlers(onAction: (action: MomentAction) => void): MomentHandlers {
  return {
    onSubmit: (answer) => onAction({ kind: "submit", answer }),
    onShowOptions: () => onAction({ kind: "show_options" }),
    onChooseOption: (choice) => onAction({ kind: "mc", choice }),
    onSkip: () => onAction({ kind: "skip" }),
    onDefer: () => onAction({ kind: "defer" }),
    onReport: () => onAction({ kind: "report" }),
  };
}

export interface MomentCardProps extends MomentHandlers {
  moment: MomentView;
  /** True while the answer is being graded. */
  grading?: boolean;
  /** XP award from the grade response (falls back to moment.xp). */
  xp?: XpAward;
  /** Hide "Quiz me later" (boss questions, wrap-up quiz). */
  canDefer?: boolean;
  autoFocus?: boolean;
  className?: string;
}

const PLACEHOLDER: Record<MomentView["type"], string> = {
  decide: "I'd go with… because…",
  predict: "I think…",
  explain_back: "In my own words…",
  spot_issue: "The issue is…",
  fill_gap: "I'd use… because…",
  boss: "Your answer…",
};

const LETTERS = ["A", "B", "C", "D", "E", "F"];

/** An inline learning moment in the chat (never a modal). States: see momentPhase(). */
export function MomentCard({ moment, grading = false, xp, canDefer = true, autoFocus = false, className = "", ...handlers }: MomentCardProps) {
  const phase = momentPhase(moment, grading);
  const sounds = useSounds();
  const headingId = useId();

  // Play the verdict sound only when new feedback arrives, never for cards restored from history.
  const fk = feedbackKey(moment);
  const lastFk = useRef(fk);
  // Feedback is "live" once it differs from what the card mounted with (restored cards stay quiet).
  const [initialFk] = useState(fk);
  const liveFeedback = fk !== null && fk !== initialFk;
  useEffect(() => {
    if (fk && fk !== lastFk.current && moment.verdict) sounds.playVerdict(moment.verdict);
    lastFk.current = fk;
  }, [fk, moment.verdict, sounds]);

  if (phase === "skipped" || phase === "deferred" || phase === "reported") {
    return <ClosedLine phase={phase} concept={moment.concept} className={className} />;
  }

  const xpAmount = xp?.amount ?? moment.xp ?? 0;
  const big = moment.type === "boss" || Boolean(xp?.levelUp);

  return (
    <section aria-labelledby={headingId} className={`rounded-card bg-primary-soft p-5 shadow-soft sm:p-6 ${className}`}>
      <div className="mb-3 flex flex-wrap items-center gap-2">
        <span className="rounded-full bg-surface px-3 py-1 text-xs font-bold tracking-wide text-primary uppercase">
          {MOMENT_TYPE_LABEL[moment.type]}
        </span>
        <span className="rounded-full border border-border px-3 py-1 text-xs font-semibold text-muted">{moment.concept}</span>
      </div>

      {moment.conceptCard && (
        <div className="mb-4 rounded-2xl bg-surface p-4 text-sm">
          <p className="mb-1 text-xs font-bold tracking-wide text-muted uppercase">Quick idea</p>
          <Markdown>{moment.conceptCard}</Markdown>
        </div>
      )}

      <div id={headingId} className="mb-4 text-lg font-semibold">
        <Markdown>{moment.question}</Markdown>
      </div>

      <p className="sr-only" aria-live="polite">
        {announcement(phase, moment)}
      </p>

      <PhaseBody phase={phase} moment={moment} xpAmount={xpAmount} big={big} canDefer={canDefer} autoFocus={autoFocus} liveFeedback={liveFeedback} handlers={handlers} />

      {phase !== "grading" && (
        <div className="mt-4 flex justify-end">
          <button
            type="button"
            onClick={handlers.onReport}
            className={`rounded text-xs text-muted hover:text-text hover:underline ${focusRing}`}
          >
            <span aria-hidden="true">⚑ </span>Report question
          </button>
        </div>
      )}
    </section>
  );
}

function announcement(phase: MomentPhase, m: MomentView): string {
  if (phase === "grading") return "Checking your answer…";
  if (phase === "locked_in") return "Locked in! Let's see what really happens.";
  if (m.verdict && (phase === "answered" || phase === "mc_answered" || phase === "choosing")) {
    return `${VERDICT_LABEL[m.verdict]}. ${m.why ?? ""}${phase === "choosing" ? " Try picking from the options." : ""}`;
  }
  return "";
}

interface PhaseBodyProps {
  phase: MomentPhase;
  moment: MomentView;
import type { MomentView, Verdict } from "@/lib/contracts/moment";

/** What a MomentCard shows, derived purely from the server's MomentView plus the client's `grading` flag. */
export type MomentPhase =
  | "question" // free-text answer box
  | "grading" // waiting for /api/moment/grade
  | "choosing" // MC options visible (after "Show options" or a "Not quite")
  | "mc_answered" // option picked: chosen + best option highlighted
  | "answered" // verdict + why + XP
  | "locked_in" // predict: waiting for the real result
  | "skipped"
  | "deferred"
  | "reported";

export function momentPhase(m: MomentView, grading = false): MomentPhase {
  if (m.status === "skipped" || m.status === "deferred" || m.status === "reported") return m.status;
  if (grading) return "grading";
  if (m.status === "awaiting_prediction_result") return "locked_in";
  if (m.mcChoice !== undefined) return "mc_answered";
  if (m.mcOptions?.length && m.verdict !== "correct") return "choosing";
  if (m.verdict) return "answered";
  return "question";
}

/** A key that changes exactly when new feedback arrives (drives the verdict sound). */
export function feedbackKey(m: MomentView): string | null {
  if (!m.verdict) return null;
  return `${m.id}:${m.verdict}:${m.mcChoice ?? "free"}`;
}

export const MOMENT_TYPE_LABEL: Record<MomentView["type"], string> = {
  decide: "Decide",
  predict: "Predict",
  explain_back: "Explain it back",
  spot_issue: "Spot the issue",
  fill_gap: "Fill the gap",
  boss: "Boss question",
};

export function pipMoodFor(verdict: Verdict, big = false) {
  if (verdict === "correct") return big ? ("celebrating" as const) : ("happy" as const);
  return "encouraging" as const;
}

