const fmtHp = (n: number) => (Number.isInteger(n) ? String(n) : n.toFixed(1));

export function BossCard({ boss, moment, grading = false, xp, momentHandlers, onContinue, continueLabel = "Continue" }: BossCardProps) {
  const sounds = useSounds();
  const [prevHp, setPrevHp] = useState(boss.hp);
  const [hits, setHits] = useState(0);
  const [hitting, setHitting] = useState(false);

  // Detect HP drops during render (React's "adjust state on prop change" pattern).
  if (boss.hp !== prevHp) {
    setPrevHp(boss.hp);
    if (boss.hp < prevHp) {
      setHits((h) => h + 1);
      setHitting(true);
    }
  }

  const outcome = boss.outcome;
  useEffect(() => {
    if (!hitting) return;
    if (!outcome) sounds.play("bossHit");
    const t = setTimeout(() => setHitting(false), HIT_MS);
    return () => clearTimeout(t);
    // `hits` restarts the hit animation for back-to-back hits.
  }, [hitting, hits, outcome, sounds]);

  const lastOutcome = useRef(outcome);
  useEffect(() => {
    if (outcome && outcome !== lastOutcome.current) {
      if (outcome === "retreat") sounds.play("reveal");
      else {
        sounds.play("bossVictory");
        void celebrate(`boss:${boss.id}`, "bossVictory");
      }
    }
    lastOutcome.current = outcome;
  }, [outcome, boss.id, sounds]);

  const defeated = outcome === "flawless" || outcome === "victory";
  const frame: BossFrame = defeated ? "defeated" : hitting ? "hit" : "full";
  const pct = boss.maxHp > 0 ? Math.max(0, boss.hp) / boss.maxHp : 0;
  const qIndex = moment ? boss.momentIds.indexOf(moment.id) : -1;

  return (
    <section aria-label={`Boss: ${boss.name}`} className="rounded-card border border-border bg-surface p-5 shadow-soft sm:p-6">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center">
        <m.div
          animate={hitting ? { x: [0, -2, 2, -2, 2, 0] } : { x: 0 }}
          transition={{ duration: 0.4 }}
          className={`w-36 shrink-0 self-center transition-opacity ${outcome === "retreat" ? "opacity-40" : ""}`}
        >
          <AsciiBoss kind={boss.ascii} frame={frame} />
        </m.div>
        <div className="min-w-0 flex-1 space-y-2">
          <p className="text-xs font-bold tracking-wide text-muted uppercase">Boss</p>
          <h3 className="text-xl font-extrabold">{boss.name}</h3>
          <p className="text-muted">{boss.intro}</p>
          <div className="flex items-center gap-3 pt-1">
            <div
              role="progressbar"
              aria-label={`${boss.name} HP`}
              aria-valuemin={0}
              aria-valuemax={boss.maxHp}
              aria-valuenow={boss.hp}
              className="h-3 flex-1 overflow-hidden rounded-full bg-surface-2"
            >
              <m.div
                className="h-full origin-left rounded-full bg-primary"
                initial={false}
                animate={{ scaleX: pct }}
                style={{ scaleX: pct }}
                transition={{ type: "spring", stiffness: 140, damping: 20 }}
              />
            </div>
            <span className="font-mono text-xs text-muted tabular-nums">
              HP {fmtHp(Math.max(0, boss.hp))}/{fmtHp(boss.maxHp)}
            </span>
          </div>
        </div>
      </div>

      {moment && (
        <div className="mt-5 space-y-2">
          {qIndex >= 0 && boss.momentIds.length > 1 && (
            <p className="text-xs font-semibold text-muted">Question {qIndex + 1} of {boss.momentIds.length}</p>
          )}
          <MomentCard key={moment.id} moment={moment} grading={grading} xp={xp} canDefer={false} {...momentHandlers} />
        </div>
      )}

      <div aria-live="polite">
        {outcome && (
          <div className="mt-5 flex flex-col items-start gap-3 rounded-2xl bg-primary-soft p-4 sm:flex-row sm:items-center">
            <div className="flex-1">
              <p className="text-lg font-extrabold">{outcomeCopy(outcome, boss.name).title}</p>
              <p className="text-muted">{outcomeCopy(outcome, boss.name).detail}</p>
            </div>
            {onContinue && <Button variant="primary" onClick={onContinue}>{continueLabel}</Button>}
          </div>
        )}
      </div>
    </section>
  );
}
  onNewSession: () => void;
}

/** End-of-session sequence: deferred quiz → Codex → XP → story → suggestions → new session. */
export function WrapUp({ data, moments, gradingMomentId, xpByMoment, onMomentAction, chapterLoading = false, onTryTheme, onSuggestion, onNewSession }: WrapUpProps) {
  const { level } = data.user;
  const rewards = data.levelUps.flatMap((l) => l.rewards);
  const pct = Math.round(levelProgress(level) * 100);

  return (
    <div className="space-y-5">
      <h2 className="text-center text-2xl font-extrabold">Session wrap-up</h2>

      {data.deferred.length > 0 && (
        <div className="space-y-3">
          <h3 className="px-1 text-sm font-bold text-muted">Quick quiz: the questions you saved for later</h3>
          {data.deferred.map((d) => {
            const m = moments?.[d.id] ?? d;
            // Saved questions reopen here for answering.
            const view: MomentView = m.status === "deferred" ? { ...m, status: "awaiting_answer" } : m;
            return (
              <MomentCard
                key={d.id}
                moment={view}
                grading={gradingMomentId === d.id}
                xp={xpByMoment?.[d.id]}
                canDefer={false}
                {...momentHandlers((a) => onMomentAction(d.id, a))}
              />
            );
          })}
        </div>
      )}

      {data.codex.length > 0 && (
        <Card aria-label="Codex">
          <h3 className="mb-3 text-lg font-extrabold">Codex</h3>
          <ul className="space-y-3">
            {data.codex.map((c) => (
              <li key={c.concept} className="flex items-start gap-3">
                <div className="min-w-0 flex-1">
                  <p className="font-bold">{c.concept}</p>
                  <p className="text-sm text-muted">{c.summary}</p>
                </div>
                <span className={`shrink-0 rounded-full border border-border bg-surface px-2.5 py-0.5 text-xs font-bold ${CODEX_CHIP[c.result].className}`}>
                  {CODEX_CHIP[c.result].label}
                </span>
              </li>
            ))}
          </ul>
        </Card>
      )}

      <Card aria-label="XP summary">
        <div className="flex items-end justify-between gap-3">
          <div>
            <p className="text-xs font-bold tracking-widest text-muted uppercase">This session</p>
            <p className="text-3xl font-extrabold text-primary">+{data.sessionXp} XP</p>
          </div>
          <p className="text-sm text-muted">Level {level.level} · {level.xp} XP total</p>
        </div>
        <div className="mt-3 h-2 overflow-hidden rounded-full bg-surface-2" aria-hidden="true">
          <div className="h-full rounded-full bg-accent" style={{ width: `${pct}%` }} />
        </div>
        <p className="mt-1 text-xs text-muted">{Math.max(0, level.nextLevelXp - level.xp)} XP to level {level.level + 1}</p>
        {rewards.length > 0 && (
          <ul className="mt-4 space-y-2">
            {rewards.map((r) => (
              <li key={`${r.kind}:${r.id}`} className="flex items-center gap-3 rounded-2xl bg-primary-soft px-4 py-2.5">
                <span className="flex-1 text-sm font-semibold">Unlocked at level {r.level}: {r.label}</span>
                {r.kind === "theme" && onTryTheme && <Button size="sm" variant="primary" onClick={() => onTryTheme(r.id)}>Try it</Button>}
              </li>
            ))}
          </ul>
        )}
      </Card>

      {(data.chapter || chapterLoading) && <StoryChapterCard chapter={data.chapter} loading={chapterLoading && !data.chapter} live />}

      {data.suggestions.length > 0 && (
        <Card aria-label="Next time">
          <h3 className="mb-3 text-lg font-extrabold">Next time you could…</h3>
          <div className="flex flex-wrap gap-2">
            {data.suggestions.map((s) => (
              <Chip key={s} onClick={() => onSuggestion(s)} className="text-left">{s}</Chip>
            ))}
          </div>
        </Card>
      )}

      <div className="flex justify-center pt-2">
        <Button variant="primary" onClick={onNewSession}>Start a new session</Button>
      </div>
    </div>
  );
}

