/**
 * Reward sounds (Track C), synthesized with the Web Audio API: no audio assets, no licenses.
 * Every pack plays the same short major-pentatonic phrases through a different "voice".
 * Loudness hierarchy (P2): click < gentle < partial < correct < bossHit < reveal/unlock < levelUp < bossVictory.
 * Nothing plays until unlock() is called from a user gesture (browser autoplay policy).
 */
import type { Verdict } from "@/lib/contracts/moment";

export type SoundEvent =
  | "click"
  | "correct"
  | "partial"
  | "gentle"
  | "reveal"
  | "unlock"
  | "levelUp"
  | "bossHit"
  | "bossVictory"
  | "streak";

export const SOUND_EVENTS: readonly SoundEvent[] = [
  "click", "correct", "partial", "gentle", "streak", "reveal", "unlock", "levelUp", "bossHit", "bossVictory",
];

export type SoundPackId = "soft-chimes" | "marimba" | "retro" | "nature";
import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  /* config options here */
  cacheComponents: true,
  partialPrefetching: true,
  turbopack: {
    rules: {
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },
};

export default nextConfig;
import { NextResponse, type NextRequest } from "next/server";
import { ACCESS_COOKIE, accessToken, decideAccess } from "@/lib/platform/access";

/** Reviewer password gate in front of every page and API route (see lib/platform/access.ts). */
export async function proxy(request: NextRequest) {
  const password = process.env.SITE_PASSWORD;
  const decision = decideAccess({
    pathname: request.nextUrl.pathname,
    cookie: request.cookies.get(ACCESS_COOKIE)?.value,
    expectedToken: password ? await accessToken(password) : null,
    production: process.env.NODE_ENV === "production",
  });

  switch (decision) {
    case "allow":
      return NextResponse.next();
    case "unauthorized":
      return NextResponse.json({ error: "Access password required." }, { status: 401 });
    case "misconfigured":
      return new NextResponse("Co-learn is not configured yet (missing site password).", { status: 503 });
    case "redirect": {
      const url = new URL("/access", request.url);
      const next = request.nextUrl.pathname + request.nextUrl.search;
      if (next !== "/") url.searchParams.set("next", next);
      return NextResponse.redirect(url);
    }
  }
}

export const config = {
  // Everything except Next.js internals and static files.
  matcher: ["/((?!_next/static|_next/image|favicon.ico|sounds/).*)"],
};
