      setNotice(errorMessage(err));
    }
  }, []);

  const loadSessions = useCallback(async () => {
    try {
      setSessions(await apiGet<SessionSummary[]>("/api/sessions"));
    } catch {
      /* drawer still works without the list */
    }
  }, []);

  return {
