    streaming,
    status,
    problem,
    notice,
    dismissNotice: () => setNotice(null),
    grading,
    xpByMoment,
    xpGain,
    levelUp,
    dismissLevelUp: () => setLevelUp(null),
    liveIds,
    bossShown,
    bossState,
    bossError,
    storyWaiting,
    wrap,
    sessions,
    send,
    sendMessage,
    act,
    startBoss,
    showBossQuestion,
    wrapUp,
    changeSettings,
    loadSessions,
    viewRef,
  };
}

export type Workspace = ReturnType<typeof useWorkspace>;

