    const anonId = await rotateAnonId();
    const user = newUser(anonId);
    await getStore().putUser(user);
    return Response.json(toUserView(user) satisfies UserView);
  } catch (e) {
    return routeErrorResponse(e, "POST /api/user/reset");
  }
}
