/** XP per event (design-plan §12). XP is only ever added, never subtracted. */
import type { BossOutcome, XpEvent } from "@/lib/contracts/engine";
import type { Verdict } from "@/lib/contracts/moment";

export const XP = {
  answer: { correct: 10, correctAfterMC: 5, partial: 5, incorrect: 0 },
  prediction: { correct: 10, partial: 5, incorrect: 0 } satisfies Record<Verdict, number>,
  bossHit: { full: 15, partial: 8 },
  // A retreat still pays: never punish.
  bossOutcome: { flawless: 75, victory: 50, retreat: 20 } satisfies Record<BossOutcome, number>,
  sessionComplete: 30,
} as const;

export function xpFor(event: XpEvent): number {
  switch (event.kind) {
    case "answer":
      if (event.verdict === "correct") return event.afterMC ? XP.answer.correctAfterMC : XP.answer.correct;
      return XP.answer[event.verdict];
    case "prediction":
      return XP.prediction[event.verdict];
    case "boss_hit":
      return event.partial ? XP.bossHit.partial : XP.bossHit.full;
    case "boss_outcome":
      return XP.bossOutcome[event.outcome];
    case "session_complete":
      return XP.sessionComplete;
  }
}
/** Resolving a graded moment: record the verdict, update mastery and engine state, award XP. */
import type { XpEvent } from "@/lib/contracts/engine";
import type { Verdict } from "@/lib/contracts/moment";
import type { MomentRecord, Session } from "@/lib/contracts/session";
import type { XpAward } from "@/lib/contracts/stream";
import type { LearningDeps } from "./deps";
import { scoreFor } from "@/lib/engine";
import { patchSession } from "./sessionStore";
import { awardXp } from "./xp";

export interface Resolution {
  verdict: Verdict;
  why: string;
  afterMC: boolean;
  missingPoints?: string[];
  mcChoice?: number;
}

export interface Resolved {
  moment: MomentRecord;
  score: number;
  xp?: XpAward;
}

export const answerXpReason = (verdict: Verdict, afterMC: boolean) =>
  verdict === "correct" ? (afterMC ? "Correct with options" : "Correct answer") : verdict === "partial" ? "Partly right" : "Answer";

export async function resolveMoment(
  deps: LearningDeps,
  session: Session,
  record: MomentRecord,
  res: Resolution,
  xp: { events: XpEvent[]; reason: string },
): Promise<Resolved> {
  const now = deps.now();
  const score = scoreFor(res.verdict, res.afterMC);
  const { concept, difficulty } = record.candidate;

  const mastery = await deps.store.getMastery(session.anonId);
  const nextMastery = deps.engine.updateMastery(mastery[concept], score, difficulty, session.intent.familiarity, now);
  await deps.store.putMastery(session.anonId, concept, nextMastery);

  await patchSession(deps, session.id, (latest) => ({
    engine: deps.engine.recordOutcome(latest.engine, { momentId: record.id, concept, type: record.type, score, at: now }),
  }));

  const award = await awardXp(deps, session.anonId, session.id, xp.events, xp.reason);

  const moment: MomentRecord = {
    ...record,
    status: "answered",
    verdict: res.verdict,
    why: res.why,
    missingPoints: res.missingPoints,
    mcChoice: res.mcChoice ?? record.mcChoice,
    xp: award?.amount ?? 0,
    answeredAt: now,
  };
  await deps.store.putMoment(moment);
  await deps.store.logEvent({
    at: now,
    anonId: session.anonId,
    sessionId: session.id,
    name: "moment_answered",
    props: { momentId: record.id, type: record.type, concept, verdict: res.verdict, afterMC: res.afterMC, score, boss: !!record.bossId },
  });
  return { moment, score, xp: award };
}
/** Boss-hit values and moment scoring (design-plan §7.3, §7.4). Outcome scores come from the engine. */
import type { Verdict } from "@/lib/contracts/moment";
import type { MomentRecord } from "@/lib/contracts/session";
import { scoreFor } from "@/lib/engine";

export const HIT = { correct: 1, afterMC: 0.5, partial: 0.5, incorrect: 0 } as const;

export function hitFor(verdict: Verdict, afterMC: boolean): number {
  if (verdict === "correct") return afterMC ? HIT.afterMC : HIT.correct;
  return verdict === "partial" ? HIT.partial : HIT.incorrect;
}

/** Score of a resolved moment, derived from its stored verdict (MC use is implied by mcChoice). */
export function momentScore(m: MomentRecord): number | null {
  if (m.status !== "answered" || !m.verdict) return null;
  return scoreFor(m.verdict, m.mcChoice !== undefined);
}

export const isSettled = (m: MomentRecord) => m.status === "answered" || m.status === "skipped" || m.status === "reported";
/** Server-side XP awarding: the client is never trusted with XP (design-plan §5.3, §12). */
import type { XpEvent } from "@/lib/contracts/engine";
import type { User } from "@/lib/contracts/session";
import type { XpAward } from "@/lib/contracts/stream";
import { newUser } from "@/lib/store/defaults";
import type { LearningDeps } from "./deps";

export async function loadUser(deps: LearningDeps, anonId: string): Promise<User> {
  return (await deps.store.getUser(anonId)) ?? newUser(anonId, deps.now());
}

/**
 * Adds the XP for `events` to the user's total, applies level rewards to their unlocks, and logs
 * level-ups. Returns undefined when the events are worth nothing.
 */
export async function awardXp(
  deps: LearningDeps,
  anonId: string,
  sessionId: string,
  events: XpEvent[],
  reason: string,
): Promise<XpAward | undefined> {
  const amount = events.reduce((sum, e) => sum + deps.engine.xpFor(e), 0);
  if (amount <= 0) return undefined;

  const user = await loadUser(deps, anonId);
  const before = deps.engine.levelFor(user.xp);
  const xp = user.xp + amount;
  const after = deps.engine.levelFor(xp);

  const award: XpAward = { amount, reason, level: after };
  const next: User = { ...user, xp, level: after.level, unlocks: { themes: [...user.unlocks.themes], soundPacks: [...user.unlocks.soundPacks] } };

  if (after.level > before.level) {
    const rewards = deps.engine.rewardsBetween(before.level, after.level);
    for (const r of rewards) {
      const list = r.kind === "theme" ? next.unlocks.themes : next.unlocks.soundPacks;
      if (!list.includes(r.id)) list.push(r.id);
    }
    award.levelUp = { from: before.level, to: after.level, rewards };
    await deps.store.logEvent({
      at: deps.now(),
      anonId,
      sessionId,
      name: "level_up",
      props: { from: before.level, to: after.level, rewards: rewards.map((r) => r.id).join(",") || null },
    });
  }

  await deps.store.putUser(next);
  return award;
}
